  const formattedDOB = `${month}${day}${year}`;
  return {
    consumers: {
      name: [{
        identifier: 'current',
        firstName: body.firstName.replace(/[^a-zA-Z0-9]/g, ' '),
        lastName: body.lastName.replace(/[^a-zA-Z0-9]/g, ' '),
        middleName: '',
        suffix: '',
      }],
      socialNum: [{ identifier: 'current', number: formattedSSN }],
      dateOfBirth: formattedDOB,
      addresses: [{
        identifier: 'current',
        streetName: `${body.address1} ${body.address2}`.trim(),
        city: body.city,
        state: body.state,
        zip: body.zipcode,
      }],
    },
    customerReferenceIdentifier: 'Pennie Management',
    customerConfiguration: {
      equifaxUSConsumerCreditReport: {
        memberNumber: '402FZ14896',
        securityCode: 'N2N',
        pdfComboIndicator: 'N',
        customerCode: 'ISTS',
        multipleReportIndicator: '1',
        ECOAInquiryType: 'Individual',
        models: [{ identifier: '05402' }],
        endUserInformation: { endUsersName: '', permissiblePurposeCode: 'Null' },
      },
    },
  };
}

async function makeEquifaxRequest(token, body) {
  try {
    const res = await fetch(
      'https://api.equifax.com/business/oneview/consumer-credit/v1/reports/credit-report',
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
          'User-Agent': 'axios/1.7.0',
          'Accept': 'application/json, text/plain, */*',
        },
        body: JSON.stringify(body),
      }
    );
    if (!res.ok) {
      const text = await res.text();
      return { error: true, statusCode: res.status, message: text };
    }
    const data = await res.json();
    return { error: false, statusCode: 200, data };
  } catch (e) {
    return { error: true, statusCode: 500, message: e.message };
  }
}

