function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function isRetryable(error) {
  // Transport / timeout errors (fetch throws TypeError on network failures,
  // AbortError when AbortSignal.timeout fires).
  if (error.name === 'AbortError') return true;
  if (error.name === 'TypeError') return true;

  const retryableStatuses = [429];
  const nonRetryableStatuses = [400, 401, 403, 404, 422];

  if (retryableStatuses.includes(error.status)) return true;
  if (error.status >= 500) return true;
  if (nonRetryableStatuses.includes(error.status)) return false;

  return true; // Default to retry for unknown errors
}

async function makeRequestWithRetry(config, maxRetries = 2, timeoutMs = 10000) {
  const baseDelay = 1000;

  // Default headers applied to every outbound request. A real User-Agent is
  // required to get past Achieve's Cloudflare WAF; Workers send none by default.
    const headers = {
    'User-Agent': 'Pennie-EligibilityScout/1.0 (+https://trypennie.com)',
    Accept: 'application/json',
    'X-Pennie-Client': 'pennie',
    ...(props.achieve_partner_key ? { 'X-Pennie-Key': props.achieve_partner_key } : {}),
    ...config.headers,
  };

  // Serialize the body based on Content-Type (axios did this implicitly).
  let body;
  const ct = headers['Content-Type'];
  if (config.data === undefined) {
    body = undefined;
  } else if (ct === 'application/x-www-form-urlencoded') {
    body = typeof config.data === 'string'
      ? config.data
      : new URLSearchParams(config.data).toString();
  } else {
    body = typeof config.data === 'string' ? config.data : JSON.stringify(config.data);
  }

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      console.log(`Attempt ${attempt + 1}/${maxRetries + 1} for ${config.url}`);

      const res = await fetch(config.url, {
        method: config.method,
        headers,
        body,
        signal: AbortSignal.timeout(timeoutMs),
      });

      if (!res.ok) {
        const text = await res.text();
        let parsed = text;
        try { parsed = JSON.parse(text); } catch {}
        const err = new Error(`HTTP ${res.status}: ${typeof parsed === 'string' ? parsed : JSON.stringify(parsed)}`);
        err.status = res.status;
        err.data = parsed;
        throw err;
      }

      const data = await res.json();
      console.log(`Request succeeded on attempt ${attempt + 1}`);
      return data;
    } catch (error) {
      const isLastAttempt = attempt === maxRetries;
      const isRetryableError = isRetryable(error);

      console.log(`Attempt ${attempt + 1} failed:`, error.message);

      if (isLastAttempt || !isRetryableError) {
        throw error;
      }

      const delayMs = baseDelay * Math.pow(2, attempt);
      console.log(`Retrying in ${delayMs}ms...`);
      await delay(delayMs);
    }
  }
}

async function getAccessToken(url, client_id, client_secret) {
  try {
    const credentials = btoa(`${client_id}:${client_secret}`);

    const data = await makeRequestWithRetry({
      method: 'POST',
      url,
      data: { grant_type: 'client_credentials' },
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Authorization: `Basic ${credentials}`,
      },
    });

    return data.access_token;
  } catch (error) {
    throw new Error(
      `Failed to get access token: ${(error.data && error.data.message) || error.message}`
    );
  }
}

async function makeRequest(url, token, correlation_id, body) {
  try {
    const data = await makeRequestWithRetry({
      method: 'POST',
      url,
      data: body,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
        'x-correlation-id': correlation_id,
      },
    });

    return {
      error: false,
      statusCode: 200,
      data,
    };
  } catch (error) {
    return {
      error: true,
      statusCode: error.status || 500,
      message: (error.data && error.data.message) || error.message,
    };
  }
}

