const ALLOWED_FIELDS = [
    'productTypes',
    'personalInformation',
    'loanInformation',
    'mortgageInformation',
    'creditInformation',
    'financialInformation',
    'educationInformation',
    'legalInformation',
    'sessionInformation',
  ];

  function sanitizeRequestBody(body) {
    const sanitizedBody = {};
    for (const field of ALLOWED_FIELDS) {
      if (field in body) sanitizedBody[field] = body[field];
    }
    return sanitizedBody;
  }

  function formatDateOfBirth(dateString) {
    if (!dateString) return dateString;
    const parts = dateString.split('-');
    if (parts.length !== 3) return dateString;
    const [year, month, day] = parts;
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }

  async function makeRequest(engineUrl, token, body) {
    try {
      const res = await fetch(engineUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(25000),
      });
      const text = await res.text();
      let parsed = text;
      try { parsed = JSON.parse(text); } catch {}
      if (!res.ok) {
        console.log('Engine error details:', res.status, parsed);
        return {
          error: true,
          statusCode: res.status,
          message: (parsed && parsed.message) || (typeof parsed === 'string' ? parsed : 'Engine request failed'),
          data: parsed,
        };
      }
      return { error: false, data: parsed };
    } catch (error) {
      console.log('Engine error details:', error);
      const isTimeout = error.name === 'TimeoutError' || error.name === 'AbortError';
      return { error: true, statusCode: isTimeout ? 504 : 500, message: error.message, data: undefined };
    }
  }

  async function makeRequestWithRetry(engineUrl, token, body) {
    console.log('Making initial request to Engine...');
    let result = await makeRequest(engineUrl, token, body);
    const retryable = result.error && (result.statusCode === 429 || (result.statusCode >= 500 && result.statusCode < 600));
    if (retryable) {
      console.log(`First request failed with ${result.statusCode}, retrying after 150ms...`);
      await new Promise((r) => setTimeout(r, 150));
      console.log('Making retry request to Engine...');
      result = await makeRequest(engineUrl, token, body);
      if (result.error) console.log(`Retry also failed with status ${result.statusCode}`);
      else console.log('Retry request succeeded!');
    }
    return result;
  }

  const body = { ...(payload ?? {}) };
  const sanitizedBody = sanitizeRequestBody(body);
  sanitizedBody.legalInformation = { ...(sanitizedBody.legalInformation || {}), consentsToTcpa: false };
  if (sanitizedBody.personalInformation?.dateOfBirth) {
    sanitizedBody.personalInformation = {
      ...sanitizedBody.personalInformation,
      dateOfBirth: formatDateOfBirth(sanitizedBody.personalInformation.dateOfBirth),
    };
  }
  if (body.Submission__c) {
    sanitizedBody.clientTags = {
      Client_id: [body.Submission__c],
    };
  }

  console.log(`Sending body to Engine: ${JSON.stringify(sanitizedBody)}`);

  const engineUrl = 'https://integrations.evenfinancial.com/blocking/leads/rateTables';
  const epc = steps.constants?.output?.epcThroughEngine;

  const fallbackToken = epc
    ? env.ENGINE_1L_PLUS_2L_TLG_5K_BEST2LOFFER
    : env.ENGINE_API_ALLPARTNERSPRODUCTION_TOKEN;

  let engineData;
  let tokenUsed;

  if (env.ENGINE_2L_ALL_TOKEN) {
    console.log('Using primary token ENGINE_2L_ALL_TOKEN...');
    engineData = await makeRequestWithRetry(engineUrl, env.ENGINE_2L_ALL_TOKEN, sanitizedBody);
    tokenUsed = 'ENGINE_2L_ALL_TOKEN';
  } else {
    console.log('ENGINE_2L_ALL_TOKEN not set, skipping to fallback token.');
  }

  if (!engineData || engineData.error) {
    if (engineData?.error) {
      console.log(`Primary token failed (${engineData.statusCode}: ${engineData.message}), falling back...`);
    }
    tokenUsed = epc ? 'ENGINE_1L_PLUS_2L_TLG_5K_BEST2LOFFER' : 'ENGINE_API_ALLPARTNERSPRODUCTION_TOKEN';
    engineData = await makeRequestWithRetry(engineUrl, fallbackToken, sanitizedBody);
  }

  console.log(`Engine request completed using ${tokenUsed} (error: ${engineData.error})`);

  if (engineData.error) {
    return {
      ok: false,
      status: engineData.statusCode,
      clientBody: { message: engineData.message, data: engineData.data },
      sfBody: null,
      engineData: null,
    };
  }

  if (!engineData.data || !engineData.data.uuid) {
    return {
      ok: false,
      status: 502,
      clientBody: { message: 'Engine returned no uuid', data: engineData.data },
      sfBody: null,
      engineData: null,
    };
  }

  const data = engineData.data;
  const elig = steps.pennie_or_eligibility?.output;
  const eligData = elig?.eligibilityData;
  const eligibility = elig?.eligibility;
  const equifaxSuccess = (elig?.equifax ?? null) !== null;
  const adv = steps.mutate_adv?.output ?? null;
  const bes = steps.mutate_bes?.output ?? null;
  const leg = body.LEG;
  const vantageScore = steps.gen_vantage_score?.output ?? null;
  const all = steps.bid_race?.output?.all_bids ?? [];
  const tripointBid = all.find((b) => b.partner === 'tripoint');
  const tripointResult = tripointBid?.extra?.result ?? null;
  const tripointLeadId = tripointBid?.extra?.leadId ?? null;
  const pennieDebt = steps.pennie_debt_calculation?.output?.pennieDebt;
  const externalDebtAmount = elig?.final;
  const now = new Date().toISOString().slice(0, 19);

  const sfBody = {
    submissionId: body.Submission__c,
    PDFlow_1__c: execution.bidspoke_link,
    External_Timestamp__c: now,
    executionId: execution.trace_id,
    PD_Completed_Timestamp__c: now,
    leadUUID: data.leadUuid,
    UUID: data.uuid,
    Monthly_Creditor_Payment_ES__c: eligData?.estimated_monthly_creditor_payment ?? null,
    Unsecured_Debt_Verified_ES__c: eligData?.estimated_total_debt ?? null,
    External_Exchange_Status__c: 'Pending',
    External_Partner_Name__c: 'Engine',
    External_Routing_Code__c: 1,
    ADV_SO__c: adv,
    XBC_SO__c: `${adv}${bes}${leg}`,
    EQXCreditPullStatus__c: equifaxSuccess ? 'Success' : 'Fail',
    LeadSaleType__c: 'Offer Wall',
    VantageScore__c: vantageScore,
    Tripoint_Response__c: tripointResult,
    TripointLeadID__c: tripointLeadId,
    EnrolledPennieDebt__c: pennieDebt,
    ExternalDebtAmount__c: externalDebtAmount,
  };
  if (eligData != null) {
    sfBody.Credit_Pull_Result_ES__c = eligibility ? 'Success' : 'Fail';
  }

  const clientBody = {
    unsecuredDebtVerified: false,
    ADV: adv,
    XBC: `${adv}${bes}${leg}`,
    routingPartner: 1,
    estimatedTotalDebt: elig?.final ?? null,
    ...data,
  };

  return { ok: true, status: 200, clientBody, sfBody, engineData: data };
